@extends('layouts.app')@section('title',__('ui.cart'))@section('content')<main class="narrow-page"><span class="micro">YOUR SELECTION</span><h1>{{ __('ui.cart') }}</h1>@if($items->isEmpty())<div class="empty-state"><b>◎</b><h2>{{ __('ui.empty') }}</h2><a href="{{ route('shop') }}">{{ __('ui.continue') }}</a></div>@else<div class="bag-list">@foreach($items as $row)@php($p=$row['product'])<div><i class="{{ $p->color }}">{{ $p->icon }}</i><span><b>{{ app()->isLocale('ar')?$p->name_ar:$p->name }}</b><small>{{ __('ui.instant') }} · ×{{ $row['quantity'] }}</small></span><strong>${{ number_format($row['line_total'],2) }}</strong><form method="post" action="{{ route('cart.remove',$p) }}">@csrf @method('DELETE')<button>Remove</button></form></div>@endforeach</div><div class="order-total"><span>{{ __('ui.total') }}</span><b>${{ number_format($items->sum('line_total'),2) }}</b></div><a class="wide-cta" href="{{ route('checkout') }}">{{ __('ui.secure') }} ↗</a>@endif</main>@endsection

